-- Fill missing configuration only; preserve all current demo overrides.
begin;
do $$ begin
 if not exists(select 1 from demo_control.environment where singleton and project_ref='srkgobayrzidytmvoago' and owner_user_id='ac1ee85e-7ed3-4ee0-adc2-59d5fea0b12a'::uuid) then raise exception 'Demo project required'; end if;
end $$;
insert into public.app_settings (id,"group",name,value,"desc")
select gen_random_uuid(),s."group",s.name,s.value,s."desc"
from jsonb_to_recordset($config$[{"group": "SYNC", "name": "SyncEngine", "value": "demo_disabled", "desc": "Sync triggers & functions defined by gpc_engine integration module"}, {"group": "SYNC", "name": "synclevel", "value": "2", "desc": "( 0 )=Sync Not used\n( 1 )=Integrator Only Rollup\n( 2 )=Farm Group Rollup\n( 3 )=Farm Level Rollup\n( 4 )=Flock Level grouped by farm\n"}, {"group": "SYNC", "name": "sync_task_que", "value": "", "desc": null}, {"group": "INTEGRATOR", "name": "company_code", "value": "DEMO", "desc": "Short integrator code used to identify related records and keep listings compact."}, {"group": "INTEGRATOR", "name": "address_line_1", "value": "", "desc": "Primary physical street address."}, {"group": "INTEGRATOR", "name": "address_line_2", "value": "", "desc": "Secondary suite, unit, or mailing line."}, {"group": "INTEGRATOR", "name": "city", "value": "", "desc": "Primary city for the integrator office."}, {"group": "INTEGRATOR", "name": "state", "value": "", "desc": "Primary state or province."}, {"group": "INTEGRATOR", "name": "postal_code", "value": "", "desc": "Primary ZIP or postal code."}, {"group": "INTEGRATOR", "name": "main_phone", "value": "", "desc": "Main office phone number."}, {"group": "INTEGRATOR", "name": "main_email", "value": "", "desc": "General mailbox for the integrator office."}, {"group": "INTEGRATOR", "name": "live_operations_contact", "value": "", "desc": "Lead contact for live operations."}, {"group": "INTEGRATOR", "name": "live_operations_phone", "value": "", "desc": "Direct phone for live operations."}, {"group": "INTEGRATOR", "name": "hatchery_contact", "value": "", "desc": "Lead hatchery contact."}, {"group": "INTEGRATOR", "name": "hatchery_phone", "value": "", "desc": "Direct phone for hatchery operations."}, {"group": "INTEGRATOR", "name": "processing_plant_contact", "value": "", "desc": "Lead processing-plant contact."}, {"group": "INTEGRATOR", "name": "processing_plant_phone", "value": "", "desc": "Direct phone for processing operations."}, {"group": "INTEGRATOR", "name": "catch_crew_contact", "value": "", "desc": "Lead catch-crew contact."}, {"group": "INTEGRATOR", "name": "catch_crew_phone", "value": "", "desc": "Direct phone for catch-crew operations."}, {"group": "INTEGRATOR", "name": "live_haul_contact", "value": "", "desc": "Lead live-haul contact."}, {"group": "INTEGRATOR", "name": "live_haul_phone", "value": "", "desc": "Direct phone for live-haul operations."}, {"group": "Placements", "name": "est_first_lh", "value": "42", "desc": "A flock is placed today, what a good guess as to when the first catch will be?  # of days after placement."}, {"group": "SYNC", "name": "do_sync", "value": "false", "desc": "SYNC Master Switch"}, {"group": "Reports", "name": "flock_history_pg3", "value": "Other Flock History", "desc": "Weight samples & Final Close-out Data"}, {"group": "SYNC-BinSentry", "name": "BulkDensity", "value": "46.1", "desc": "Bulk Density setting to use in lbs/cu.Ft. of feed.  This number is used to place a 'weight' on the cubic feet of volume of feed in each feed bin."}, {"group": "Placements", "name": "grow_out_days", "value": "46", "desc": "When scheduling future placements, the Placement Wizard blocks this many days for the flock to complete and allow 10-14 days downtime before allowing another flock to be scheduled.  Another way of thinking about this number is the number of days in the future that it checks for \"Open\" dates before allowing a placement to be booked."}, {"group": "General", "name": "sort_by_sort_code", "value": "false", "desc": "True: \nBarns, Flocks, Placements for Dashboard display,          combo box lists and most reports will arrange barns based on the generic/user defined \"sort_code\" field on each barn's configuration.\n\nFalse: (Default)\nBarns, flocks and placements will appear arranged by barn_code from the barn's configuration.\n"}]$config$::jsonb) as s("group" text,name text,value text,"desc" text)
where not exists(select 1 from public.app_settings d where lower(trim(d.name))=lower(trim(s.name)));
insert into platform.screen_txt (name,display,note,scrn_location)
select s.name,s.display,s.note,s.scrn_location
from jsonb_to_recordset($copy$[{"name": "copyright", "display": "Copyright © 2026  All rights reserved.  Smotherman Farms, Ltd.  West, Texas USA", "note": "legal copyright tag", "scrn_location": "list: anywhere the copyrigh s/b displayed.\n1) splash"}, {"name": "farm_barn_desc", "display": "This setup/configuration screen defines the backbone of the FlockTrax System and their relationship to each other.  The hierarchy: Barns belong to Farms, Farms belong to Groups & Groups become FlockTrax.", "note": "The description is displayed in a lightweight font just below the Groups-Farms & Barns setup title and tries to give a more verbose description of the screen's function        ", "scrn_location": "Groups-Farms & Barns Setup Screen"}, {"name": "feed_bin_title", "display": "Configure Feed Bins Assigned to Barns", "note": "This is the title of the console sacxreen that defines and links feed bins to barns", "scrn_location": "Console setup screen for feed bins."}, {"name": "feed_bin_desc", "display": "This setup screen allows you create Feed Bin that are located at each of your barns.  These will be used to record feed deliveries on the mobile app.  This is also a hierarchy relationship:  Bins belong to Barns & Barns belong to Farms", "note": "more verbose description of the setup screens function.", "scrn_location": "setup screen for feed bins"}, {"name": "flock_scheduler_title", "display": "Create Flocks & Schedule Placements", "note": "Title of the calendar scheduler", "scrn_location": "placement wizard"}, {"name": "flock_scheduler_desc", "display": "Interactive calendar to schedule a Placement Date and create a flock record, effectively 'reserving' a barn for a period of time to raise the new flock.", "note": "verbose description of the title", "scrn_location": "placement wizard menu option"}, {"name": "calendar_farm_view", "display": "Displays all placements for all barns on a single calendar", "note": "discribes what farm_view is for", "scrn_location": "placement wizard calendar view toggle"}, {"name": "calendar_barn_view", "display": "Displays a single barn for scheduling placements & editing existing ones", "note": "describes the barn view on placement wizard", "scrn_location": "placement wizard barn view mode"}, {"name": "placement_wizard_desc", "display": "In Barn View mode allows scheduling & editing of placements.  In Farm View mode displays all placements for all barns at a farm on a single calendar.", "note": "placement wizard main title verbose description", "scrn_location": "Placement wizard hero block"}, {"name": "audit_log_title", "display": "Activity Log", "note": "system diary ", "scrn_location": "audit log\n"}, {"name": "audit_log_desc", "display": "This archive maintains a chronological narrative of the system, barn activity, comments, and state changes.", "note": "audit log", "scrn_location": "audit log"}, {"name": "archive_flocks_title", "display": "Archived Flock Records", "note": "archive menu section", "scrn_location": "archived menu - flocks"}, {"name": "archive_flocks_desc", "display": "Any flock record that is not scheduled for a future date, currently in the barn or has not been flagged as Complete.", "note": "Archive Record description", "scrn_location": "Archives - Flocks"}, {"name": "archive_flocks_filter", "display": "Filter by flock, integrator, or placed date to narrow the archive. Clicking a record will open the record for detail access.", "note": "archive filter helper", "scrn_location": "archive-flocks list helper"}, {"name": "farm_barn_title", "display": "Create & Edit Farm Groups, Farms & Barns", "note": "This is the bold screen title for the setup/configuration screen where the Farm_Groups, Farms & Barns are defined and linked together to form the backbone of the system.", "scrn_location": "Title Group-Farm-Barn Setup"}, {"name": "log_filter_desc", "display": "Filter by date, farm, barn, flock, or user to narrow the operating history. Clipped fields (...) may be displayed by clicking.", "note": "filter help info", "scrn_location": "activity log listing "}, {"name": "admin_feed_title", "display": "Feed Accounting", "note": "Feed Ticket allocation to feed bins when received, accounting for feed movements between flocks or between farms.  Accounting for feed remaining after a flock has completed and transferring that feed to the next flock placed in the same barn.", "scrn_location": "Admin Console - Feed Tickets"}, {"name": "lh_scheduler_title", "display": "Livehaul Scheduler", "note": "main title of livehaul scheduler", "scrn_location": null}, {"name": "lh_scheduler_desc", "display": "Create & edit livehaul events.  Similar to scheduling placements, this edit schedules the placements loadout for processing.", "note": "description of schedule screen", "scrn_location": "livehaul schedule"}, {"name": "admin_install_title", "display": "Install FlockTrax-Admin Console", "note": "Title of the install option on the sidebar menu option \"About\"", "scrn_location": "SidebarMenu.About"}, {"name": "placement_wizard_title", "display": "Placement Scheduler", "note": "title of screen by same menu option name", "scrn_location": "placement wizard main screen title"}, {"name": "install_admin_details", "display": "Add FlockTrax-Admin Console with the FlockTrax icon on this computer's desktop.  The app will open in its own application window from the Windows desktop or Start menu.", "note": "functionality will remain browser based but will have a higher level of control in its own application window.", "scrn_location": "SidebarMenu.About.InstallFlockTrax"}, {"name": "action_type_helper", "display": "Code: \r\nInternal code used to record selection.\r\n\r\nLabel:\r\nDisplayed text of the selection.\r\n\r\nBelongs to:\r\nWhat this action item is linked to the barn or the flock in the barn.\r\n\r\nSort Oder: \r\nAllows the list to be displayed in any order\r\n\r\nDefault Tone:\r\nDetermines how much emphasis is placed on the severity of this issue as far as indicators on the dashboard screens.\r\n\r\nReport Group:\r\nFuture enhancement for printed reports", "note": "", "scrn_location": "used on the action type maintenance screen as helper text\n"}, {"name": "feed_help_ticket", "display": "Enter the delivery ticket/order number exactly as i appears on the document, including leading or trailing zeros.", "note": "field options help", "scrn_location": "Feed Tickets/Filters"}, {"name": "feed_help_ticket_type", "display": "   Reg:   Normal incoming feed ticket\nxTran:   External transfer of feed to another Farm Group\n iTran:   Internal transfer of feed between feed bins\n              belonging to the same Farm Group.\n     f2f:   Feed transfer between flocks using the same \n              barn. (i.e. remaining feed credited to next flock)\n", "note": "explaination of different feed ticket types", "scrn_location": "feed tickets"}, {"name": "feed_help_redirected_drops", "display": "Redirected Drop is a portion of an ordered load of feed that was listed on the delivery ticket as being sent to your farm, but was \"redirected\" to another farm to cover an out-of-feed emergency at the other farm.", "note": "Use this redirected drop to account for feed shown on your feed ticket that was actually dropped on another farm.", "scrn_location": "feed tickets"}, {"name": "feed_help_queued_drop", "display": "A Queued Drop is used to account for feed that was not dropped on the farm, but shows on the feed delivery ticket as being delivered.  Monitoring system does not show the feed being dropped.  Queued drops are not charged to a flock's feed record.", "note": "Queued drops are need to allocate the total balance of a delivery ticket when the monitoring system does not show the feed being delivered.", "scrn_location": "feed tickets"}, {"name": "feed_help_feedmill", "display": "Enter the Name of the feed mill making the feed associated with this delivery ticket", "note": "name of feed mill. freeform entry", "scrn_location": "feed tickets\n"}, {"name": "admin_feed_desc", "display": "Create & maintain accurate records of feed received and account for transferring feed between farms, barns & flocks.\r\n\r\nIf multiple entries for farms, bins or flocks are included in the listing line, press \"...\" button to display the multiple entries.", "note": "", "scrn_location": "Admin Console Menu item.Feed Tickets"}]$copy$::jsonb) as s(name text,display text,note text,scrn_location text)
where not exists(select 1 from platform.screen_txt d where lower(trim(d.name))=lower(trim(s.name)));
-- Save the merged settings, including existing demo overrides, as the reset baseline.
insert into demo_control.app_settings_seed (id,setting_group,setting_name,setting_value,setting_description)
select id,"group",name,coalesce(value,''),coalesce("desc",'') from public.app_settings
on conflict(id) do update set setting_group=excluded.setting_group,setting_name=excluded.setting_name,
 setting_value=excluded.setting_value,setting_description=excluded.setting_description;
commit;
